    stockSubscriptionOffers(),
  ])
  const stockKeys = new Set(stock.map(offer => `${offer.route}::${offer.modelId}`))
  const offers = [
    ...acp.filter(offer => !stockKeys.has(`${offer.route}::${offer.modelId}`)),
    ...commandCode,
    ...stock,
